import static bootcamp.Check.*;

import java.util.*;
import java.util.function.*;

class Exercise {

    enum Scope { SINGLETON, PROTOTYPE }
    interface Notifier { String channel(); }
    record Email(String channel) implements Notifier {}
    record Sms(String channel) implements Notifier {}
    static final class Clock {}
    record Service(Notifier notifier, Clock clock) {}

    static final class Container {
        private static final class Reg {
            final String name; final boolean primary; final Scope scope; final Function<Container, ?> factory;
            Object instance;
            Reg(String name, boolean primary, Scope scope, Function<Container, ?> factory) { this.name = name; this.primary = primary; this.scope = scope; this.factory = factory; }
        }
        private final Map<Class<?>, List<Reg>> regs = new HashMap<>();

        <T> void register(Class<T> type, String name, boolean primary, Scope scope, Function<Container, ? extends T> factory) {
            regs.computeIfAbsent(type, k -> new ArrayList<>()).add(new Reg(name, primary, scope, factory));
        }

        <T> T get(Class<T> type) {
            var candidates = regs.getOrDefault(type, List.of());
            if (candidates.isEmpty()) throw new IllegalStateException("no bean of type " + type.getSimpleName());
            if (candidates.size() == 1) return type.cast(instance(candidates.get(0)));
            var primaries = candidates.stream().filter(r -> r.primary).toList();
            if (primaries.size() != 1) throw new IllegalStateException("expected single matching bean but found " + candidates.size());
            return type.cast(instance(primaries.get(0)));
        }

        <T> List<T> getAll(Class<T> type) {
            var out = new ArrayList<T>();
            for (var r : regs.getOrDefault(type, List.of())) out.add(type.cast(instance(r)));
            return out;
        }

        private Object instance(Reg r) {
            if (r.scope == Scope.PROTOTYPE) return r.factory.apply(this);
            if (r.instance == null) r.instance = r.factory.apply(this);
            return r.instance;
        }
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("singletons are shared, prototypes are new", () -> {
            var c = new Container();
