            ok(c.get(Clock.class) == c.get(Clock.class), "singleton must be shared");
            ok(c.get(Notifier.class) != c.get(Notifier.class), "prototype must be new");
        });
        test("the primary bean wins among several", () -> {
            var c = new Container();
            c.register(Notifier.class, "email", true, Scope.SINGLETON, x -> new Email("email"));
            c.register(Notifier.class, "sms", false, Scope.SINGLETON, x -> new Sms("sms"));
            eq(c.get(Notifier.class).channel(), "email");
            eq(c.getAll(Notifier.class).stream().map(Notifier::channel).toList(), List.of("email", "sms"));
        });
        test("several candidates without one primary fail", () -> {
            var c = new Container();
            c.register(Notifier.class, "email", false, Scope.SINGLETON, x -> new Email("email"));
            c.register(Notifier.class, "sms", false, Scope.SINGLETON, x -> new Sms("sms"));
            ok(raises(IllegalStateException.class, () -> c.get(Notifier.class)).getMessage().contains("found 2"), "message should say found 2");
        });
        test("factories resolve their dependencies", () -> {
            var c = new Container();
            c.register(Clock.class, "clock", false, Scope.SINGLETON, x -> new Clock());
            c.register(Notifier.class, "email", false, Scope.SINGLETON, x -> new Email("email"));
            c.register(Service.class, "service", false, Scope.SINGLETON, x -> new Service(x.get(Notifier.class), x.get(Clock.class)));
            ok(c.get(Service.class).clock() == c.get(Clock.class), "the service got the shared clock");
